  it('error still propagates after onError hook', async () => {
    const hooks: OrchestratorHooks = {
      onError: async () => {},
    };

    const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
      hooks,
    });
    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
  });

  const rejectionTurn = async (reason: unknown) => {
    let seenError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        seenError = error;
      },
    };
    const orchestrator = createChatOrchestrator(createErrorProvider(reason), promptBuilder, undefined, {hooks});
    const thrown = await orchestrator.processMessage(createSession('hello')).then(
      value => value as unknown,
      (caught: unknown) => caught
    );
    return {
      thrown,
      isError: seenError instanceof Error,
      message: seenError?.message,
      cause: seenError?.cause,
    };
  };

  it('wraps a thrown string, plain object, or undefined in an Error with cause while rethrowing the original', async () => {
    const reason = {code: 503, detail: 'upstream down'};

    const outcomes = [
      await rejectionTurn('string boom'),
      await rejectionTurn(reason),
      await rejectionTurn(undefined),
    ];

    expect(outcomes).toEqual([
      {thrown: 'string boom', isError: true, message: 'string boom', cause: 'string boom'},
      {thrown: reason, isError: true, message: '[object Object]', cause: reason},
      {thrown: undefined, isError: true, message: 'undefined', cause: undefined},
    ]);
  });
});

